"""Source coverage, native visual decisions, and composition verification for this batch."""
import json,sys,hashlib,sqlite3
from pathlib import Path
W=Path(__file__).resolve().parent;ROOT=W.parents[2];sys.path.insert(0,str(ROOT))
from icon_set.model.icons.registry import create
from icon_set.scripts.compose import compose
from icon_set.scripts.primitive_status import init_primitive_status,set_status
rows=json.loads((W/'batch.json').read_text());c=json.loads((W/'candidates.json').read_text());qa=json.loads((W/'release-qa.json').read_text())
HOLD={1: ('Three rising rounded candlestick bodies, each with upper and lower wick.', 'Three open bodies and all six wicks have no verified source-faithful SUB32 layout with legal parallel spacing. Retain all three candles; no reduced chart was activated. Complete source and centerline rechecked in batch 6; still unresolved.'), 2: ('Rocket body with pointed curved nose, open arched cockpit, TWO side fins, flat base and central lower stem.', 'The narrow fins and enclosed cockpit-to-body spacing remain unresolved with a 4px stroke. Parent also altered the flat base into a small curve. A complete repair must retain the arched cockpit, fins, base and stem; no simplified rocket is activated. Rechecked against the complete original in batch 5; this issue remains unresolved.'), 3: ('Eight-lobed rosette, circular center hole and one notched ribbon.', 'The center hole must remain visibly open while the scalloped seal and lower ribbon retain separate spaces. No complete 32px/4px-stroke layout has been verified; do not flatten the rosette into a generic medal or fill its center. Rechecked against the complete original in batch 5; this issue remains unresolved.'), 4: ('Rounded document with clipped upper-right corner and inner rectangle divided into two cells.', 'This source is a framed two-cell drawing, not text RTF. The nested frame and divider require more internal parallel spacing than the available envelope; no complete compliant candidate is verified. Complete source and centerline rechecked in batch 6; still unresolved.'), 5: ('Indian rupee character with two upper bars, curved bowl and diagonal lower leg.', 'The shared typeface catalog lacks the rupee character. Do not replace it with a new one-off currency glyph. Complete source and centerline rechecked in batch 6; still unresolved.'), 6: ('Seated electric scooter with two open wheels, seat and stem, low chassis and tall steering handle.', 'Candidate retained for another repair: mic [frame]: frame and front are 2.14129 apart on centerlines nearest (20.6122, 21.0531)<->(22.4882, 22.0856); SUB32 requires at least 6 (ink clearance 2) unless the contact is declared with a scoped `connect` relationship; internal-spacing [front / frame]: front-top and rise have -1.8578 units of ink clearance over 4.8182 units; requires 2; review required; internal-spacing [steering / frame]: steering-2 and rise have -1.1103 units of ink clearance over 2.2982 units; requires 2; review required; internal-spacing [frame / post]: rise and post have 0.4978 units of ink clearance over 3.7735 units; requires 2; review required Complete source and centerline rechecked in batch 6; still unresolved.'), 7: ('Shield outline and closed five-point star.', 'The existing star fails facing-edge spacing (6 and 6.32456 versus 8 centerline units). Enlarging it must also retain six-unit separation from the shield. No complete clear star-in-shield layout is established; do not substitute an asterisk or filled mark. Rechecked against the complete original in batch 5; this issue remains unresolved. Complete source and centerline rechecked in batch 6; still unresolved.'), 8: ('Shared typeface digit-0, symbol-percent; natural proportions, 32-unit ink height and grid-fitted layout.', 'Candidate retained for another repair: mic [path-2-1]: path-2-1 and path-3-1 are 5.47494 apart on centerlines nearest (40.0616, 14.5137)<->(35.6065, 11.3315); SUB32 requires at least 6 (ink clearance 2) unless the contact is declared with a scoped `connect` relationship; mic [path-2-1]: path-2-1 and path-4-1 are 5.47494 apart on centerlines nearest (37.9384, 17.4863)<->(42.3935, 20.6685); SUB32 requires at least 6 (ink clearance 2) unless the contact is declared with a scoped `connect` relationship Rechecked against the complete original in batch 5; this issue remains unresolved.'), 9: ('Two Wi-Fi arcs, trapezoidal windshield, rounded bumper and TWO wheel stems.', 'The parent omitted both wheel stems. Restoring both wheels, two wireless arcs and the enclosed windshield/bumper requires additional vertical clearances. No complete 32px layout is verified; do not remove a Wi-Fi arc or wheel to force a pass. Rechecked against the complete original in batch 5; this issue remains unresolved.'), 10: ('Rounded enclosing square with FIVE vertical barcode strokes of alternating lengths.', 'The parent reduced five bars to three. Five parallel bars require four 8-unit intervals before adding clearance to the frame, exceeding the 28-unit centerline envelope. Full source retained for review. Rechecked against the complete original in batch 5; this issue remains unresolved.'), 11: ('Enclosing circle and two-bar equals character.', 'The shared symbol-equals glyph has a width-to-gap ratio of 26:12. At the required eight-unit parallel gap its width exceeds the legal interior of the enclosing circle. The narrower draft passes geometry but distorts shared-glyph proportions, so it is not activated. Complete source and centerline rechecked in batch 6; still unresolved.'), 12: ('Full registered trademark: enclosing circle and capital R.', 'Must reuse shared letter-r-uppercase inside the complete enclosing circle. Its bowl and diagonal leg require a new layout with an open counter and frame clearance; no compliant complete placement is verified. Do not remove the circle. Complete source and centerline rechecked in batch 6; still unresolved.'), 13: ('Enclosing circle and pound character.', 'The pound character is absent from the shared typeface catalog. The complete circle must be preserved; a plain standalone currency mark cannot replace this original. Complete source and centerline rechecked in batch 6; still unresolved.'), 14: ('Diagonal syringe barrel, rounded nose, needle, plunger shaft and cap; TWO graduation ticks.', 'Parent omitted one of the two graduation ticks. Barrel, plunger cap and both ticks require repeated eight-unit parallel spacing along a short diagonal body. A complete layout remains unresolved; the one-tick parent is not an accepted repair. Rechecked against the complete original in batch 5; this issue remains unresolved. Complete source and centerline rechecked in batch 6; still unresolved.'), 15: ('Rounded tactic board containing two X marks, an open circle and curved upward arrow.', 'Earlier profile removes one X and closes the circle. No complete layout preserving both X marks, circle, arrow and surrounding frame has been verified at fixed 32px and 4px stroke. Complete source and centerline rechecked in batch 6; still unresolved.'), 16: ('Shared typeface letter-d-uppercase, letter-w-uppercase, letter-g-uppercase at 32px ink height and natural width.', 'Shared glyphs retained and rounded W turns preserved during grid fitting, but full inspection still reports internal spacing warnings between the W branches. No glyph replacement, nonuniform stretch, or validator exemption was used. The candidate remains a review draft.'), 17: ('Shared typeface letter-w-uppercase, letter-a-uppercase, letter-v-uppercase at 32px ink height and natural width.', 'Shared glyphs retained and rounded W turns preserved during grid fitting, but full inspection still reports internal spacing warnings between the W branches. No glyph replacement, nonuniform stretch, or validator exemption was used. The candidate remains a review draft.'), 18: ('Three repeated vertical lightning zigzags, each with two diagonal legs and horizontal middle.', 'The parallel diagonal legs of each bolt fail the eight-unit centerline spacing rule. Widening three complete bolts while keeping them separate exceeds this envelope; the draft is retained for review, not activated. Complete source and centerline rechecked in batch 6; still unresolved.'), 19: ('Open circular face outline, curved hair part, complete pointer with diagonal trailing stem.', 'Parent omitted the hair part and pointer stem. Full head/hair and pointer need separate clearances; the existing simplified candidate has no source-coverage approval. Requires a complete redraw, not just cleaning its circle. Rechecked against the complete original in batch 5; this issue remains unresolved. Complete source and centerline rechecked in batch 6; still unresolved.'), 20: ('Rounded wallet with right fastening tab and angled protruding cash bill.', 'Candidate retained for another repair: mic [tab]: parallel straight edges tab-4 and base are 4 apart on centerlines (ink gap 0); requires at least 8 centerline / 4 ink (midpoint-normal); internal-spacing [upper / cash]: top and cash-1 have -3.6923 units of ink clearance over 11.6593 units; requires 2; review required; internal-spacing [lower / tab]: base and tab-5 have 0.1358 units of ink clearance over 2.75 units; requires 2; review required'), 21: ('Korean won character: W-shaped stroke with horizontal currency bar.', 'No matching won glyph exists in the shared typeface catalog. Keep the original character pending a shared-glyph solution; a newly invented W/bar symbol is not accepted.')}

for n in [20]:HOLD.pop(n,None)

audit=[];accepted=[];compositions={}
for r in rows:
 n=r['number'];assert Path(r['source_path']).is_file()
 assert hashlib.sha256(Path(r['source_path']).read_bytes()).hexdigest()==r['source_sha256']
 assert hashlib.sha256((ROOT/r['python_source']).read_bytes()).hexdigest()==r['parent_sha256']
 e=dict(r,parent_preserved=True,source_sha256=hashlib.sha256(Path(r['source_path']).read_bytes()).hexdigest())
 current=json.loads((W/'current-checks.json').read_text())[str(n)]
 e.update(current_status=current['status'],current_findings=current.get('errors',[])+current.get('warnings',[]),complete_source_reviewed=True)
 if str(n) in c:
  cand=c[str(n)];m=create(cand['icon']);sv=m.to_svg();q=qa[str(n)];assert q['svg_sha256']==hashlib.sha256(sv.encode()).hexdigest()
  e.update(candidate=cand['icon'],candidate_python=cand['python_source'],source_parts=cand['parts'],repair=cand['parts'],construction_reference=cand['lucide_reference'],candidate_status=q['status'],candidate_findings=q.get('errors',[])+q.get('warnings',[]))
  if q['status']!='pass' and n not in HOLD:HOLD[n]=(cand['parts'],'Candidate retained for another repair: '+'; '.join(e['candidate_findings']))
 if n in HOLD:
  parts,reason=HOLD[n];e.update(source_parts=parts,outcome='unresolved',primitive_status='skip',previous_variant_needs_review=True,reason=reason,source_coverage_pass=False)
 else:
  assert m.validate_icon().status=='valid'
  cq=compose('container-circle',cand['icon']).validate_icon()
  if getattr(m,'text_canvas_width',32)>32:
   assert m.text_canvas_width>32
   compositions[str(n)]={'icon':cand['icon'],'status':'not_applicable_wide_text','container_circle_status':cq.status,'findings':cq.describe(),'reason':'User explicitly requested natural-width shared-glyph text with 32px ink height. Container-circle placement is not compatible with this width; no scaling or glyph distortion applied. Validate its eventual side placement separately.'}
  else:
   assert cq.status=='valid',cq.describe()
   compositions[str(n)]={'icon':cand['icon'],'status':cq.status,'findings':cq.describe()}
  e.update(outcome='repaired',reason=cand['parts']+(' Natural-width text: square container placement is not applicable; side placement must accommodate its full width.' if getattr(m,'text_canvas_width',32)>32 else ''),source_coverage_pass=True,visual_review='Complete original compared with native light/dark renders and enlarged centerlines. Counts, directions, loops and frames retained. No human approval implied.')
  accepted.append(e)
 if e['outcome']=='unresolved':
  reason=e['reason'].lower()
  e['blocker_group']='Missing shared glyph' if any(t in reason for t in ('no matching','no pound glyph','does not contain','lacks a','lacks the','has no pound','no preferred bitcoin','no dedicated prescription','no shared bitcoin','absent from','matching shared-glyph')) else 'Spacing / source-complete redraw'
 audit.append(e)
for name,data in [('audit',audit),('accepted',accepted),('composition-checks',compositions)]: (W/(name+'.json')).write_text(json.dumps(data,indent=2))
(W/'primitive-status.sqlite3').unlink(missing_ok=True)
con=sqlite3.connect(W/'primitive-status.sqlite3');init_primitive_status(con)
for e in audit:
 if e['outcome']=='unresolved':set_status(con,[e['source_uuid']],'skip','other',e['reason'],user='gpt-6',record=lambda *a,**k:None)
con.commit();con.close()
(W/'primitive-status.json').write_text(json.dumps({e['source_uuid']:{'status':'skip','icon':e['icon'],'note':e['reason']} for e in audit if e['outcome']=='unresolved'},indent=2))
print(len(accepted),'repaired;',len(rows)-len(accepted),'unresolved; all original models preserved.')
